// Deduplicate by Vapi call ID so the same end-of-call report
// is never processed twice (e.g. Vapi retries, or a manual re-send).
const staticData = $getWorkflowStaticData('global');
if (!staticData.seenCallIds) staticData.seenCallIds = [];

const callId = $input.first().json.body?.message?.call?.id
            || $input.first().json.body?.call?.id
            || null;

if (!callId) {
  // No call id present - let it through but flag it, so it is not silently dropped.
  return [{ json: { ...$input.first().json, _dedupe: 'no-call-id' } }];
}

if (staticData.seenCallIds.includes(callId)) {
  // Already processed this call - stop here.
  return [];
}

staticData.seenCallIds.push(callId);
// Keep the list from growing forever.
if (staticData.seenCallIds.length > 5000) {
  staticData.seenCallIds = staticData.seenCallIds.slice(-2000);
}

return [{ json: { ...$input.first().json, _dedupe: 'new' } }];
